mapper.select:
SELECT distinct t.TRADE_ID tradeId,/**交易编号**/ null outTradeId, /*外部成交编号*/ deal.BOOKSET_ID prodId,/**金融产品代码**/ bok.BOOKSET_NAME prodName,/**金融产品名称**/ zc.FINPROD_MARKET_ID assetId, /**资产代码**/ zc.FINPROD_ABBR assetName,/**资产简称**/ t.PS ps,/**交易方向**/ t.TRADE_DATE tradeDate,/**交易日**/ t.SETTLE_DATE effDate,/**交割日期**/ t.INV_AIM invAim,/**投资目的**/ t.PRIN_AMT capital,/**本金金额**/ t.CPRICE_AMT cpriceAmt,/**净价总额**/ t.INT_AMT intAmt,/**应收利息总额**/ t.CCY ccy,/**币种**/ stl.SETTLE_AMT settleAmt,/**结算金额**/ stl.MY_ACCT_NO myAcctNo/**资金账户**/ FROM TRD_PRODUCT_DEAL t LEFT JOIN FIN_PRODUCT zc on zc.finprod_id = t.finprod_id LEFT JOIN BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = t.TRADE_ID LEFT JOIN BOK_BOOKSET bok on bok.BOOKSET_ID = deal.BOOKSET_ID LEFT JOIN STL_ORDERS stl ON stl.TRADE_ID = t.TRADE_ID AND stl.BUSI_TYPE ='09' and stl.ORDER_TYPE NOT LIKE 'N%' where t.BUSI_TYPE ='09' and t.FINPROD_TYPE = 'F17'
and t.TRADE_ID like concat(concat('%',#{tradeId}),'%')
and deal.BOOKSET_ID IN
#{finprodId}
and zc.FINPROD_MARKET_ID IN
#{assetId}
AND t.PS IN
#{ps}
order by t.TRADE_ID desc

select FINPROD_MARKET_ID id, FINPROD_ABBR text from FIN_PRODUCT
1=1
and FINPROD_TYPE = #{assetType}
AND FINPROD_MARKET_ID = #{initValue}
AND (FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select p.FINPROD_ID id, p.FINPROD_ABBR text from FIN_PRODUCT p
1=1
and FINPROD_TYPE =#{finprodType}
AND FINPROD_ID = #{initValue}
AND (FINPROD_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))
